  let next = 0;
  const workerCount = Math.min(Math.max(1, limit), list.length || 1);
  await Promise.all(Array.from({ length: workerCount }, async () => {
    while (next < list.length) {
      const index = next++;
      out[index] = await mapper(list[index], index);
    }
  }));
  return out;
}

